def diamond_square(n, corners, jitter, roughness=1.0):
    if n < 1:
        raise ValueError("n must be at least 1")
    size = 2 ** n + 1
    grid = [[None] * size for _ in range(size)]
    last = size - 1
    tl, tr, bl, br = corners
    grid[0][0] = tl
    grid[0][last] = tr
    grid[last][0] = bl
    grid[last][last] = br

    def average(values):
        present = [v for v in values if v is not None]
        if not present:
            raise ValueError("no known neighbours to average")
        return sum(present) / len(present)

    step = last
    amplitude = 1.0
    while step > 1:
        half = step // 2
        for y in range(half, last, step):
            for x in range(half, last, step):
                grid[y][x] = average([
                    grid[y - half][x - half], grid[y - half][x + half],
                    grid[y + half][x - half], grid[y + half][x + half],
                ]) + amplitude * jitter(x, y)
        for y in range(0, last + 1, half):
            start = half if (y // half) % 2 == 0 else 0
            for x in range(start, last + 1, step):
                grid[y][x] = average([
                    grid[y - half][x] if y >= half else None,
                    grid[y + half][x] if y + half <= last else None,
                    grid[y][x - half] if x >= half else None,
                    grid[y][x + half] if x + half <= last else None,
                ]) + amplitude * jitter(x, y)
        amplitude *= 0.5 ** roughness
        step = half
    return grid
